            test("(number, T) → fail, -500",            () => expect(() => newInstance(null, undefined,).indexOfLastIndexed(callbackAsFail2, -500,),)                .toThrow(IndexOutOfBoundsException,),)
            test("(number, T) → fail, 2",               () => expect(() => newInstance(null, undefined,).indexOfLastIndexed(callbackAsFail2, 2,),)                   .toThrow(IndexOutOfBoundsException,),)
            test("(number, T) → fail, 500",             () => expect(() => newInstance(null, undefined,).indexOfLastIndexed(callbackAsFail2, 500,),)                 .toThrow(IndexOutOfBoundsException,),)
            test("(number, T) → fail, +∞",              () => expect(() => newInstance(null, undefined,).indexOfLastIndexed(callbackAsFail2, Infinity,),)            .toThrow(ForbiddenIndexException,),)
            test("(number, T) → fail, NaN, NaN",        () => expect(() => newInstance(null, undefined,).indexOfLastIndexed(callbackAsFail2, NaN, NaN,),)            .toThrow(ForbiddenIndexException,),)
            test("(number, T) → fail, NaN, -∞",         () => expect(() => newInstance(null, undefined,).indexOfLastIndexed(callbackAsFail2, NaN, -Infinity,),)      .toThrow(ForbiddenIndexException,),)
